SET NAMES utf8mb4;

CREATE DATABASE IF NOT EXISTS dw DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
GRANT ALL PRIVILEGES ON dw.* TO 'lzs'@'%';
USE dw;

DROP TABLE IF EXISTS fact_orders;
DROP TABLE IF EXISTS dim_member;
DROP TABLE IF EXISTS dim_product;
DROP TABLE IF EXISTS dim_store;
DROP TABLE IF EXISTS dim_date;

CREATE TABLE dim_store
(
    store_id   VARCHAR(10) PRIMARY KEY,
    store_name VARCHAR(50),
    city       VARCHAR(30),
    store_type VARCHAR(20) COMMENT '门店类型：办公区/社区/商场',
    open_date  DATE,
    staff_count INT
);

CREATE TABLE dim_product
(
    product_id   VARCHAR(10) PRIMARY KEY,
    product_name VARCHAR(50),
    category     VARCHAR(20),
    unit_price   DECIMAL(6,2),
    rating       DECIMAL(2,1) COMMENT '大众点评评分（0~5）',
    launch_date  DATE,
    is_cobrand   VARCHAR(4) COMMENT '是否联名款：是/否'
);

CREATE TABLE dim_date
(
    date_id    INT PRIMARY KEY,
    year       INT,
    quarter    VARCHAR(2),
    month      INT,
    day        INT,
    weekday    VARCHAR(4) COMMENT '星期一~星期日',
    is_weekend VARCHAR(4) COMMENT '是否周末：是/否'
);

CREATE TABLE dim_member
(
    member_id     VARCHAR(10) PRIMARY KEY,
    member_name   VARCHAR(30),
    member_level  VARCHAR(10) COMMENT '会员等级：普通/白银/黄金',
    register_date DATE
);

CREATE TABLE fact_orders
(
    order_id       VARCHAR(30) PRIMARY KEY,
    store_id       VARCHAR(10),
    product_id     VARCHAR(10),
    date_id        INT,
    member_id      VARCHAR(10) NULL COMMENT '会员ID；NULL = 非会员匿名下单',
    channel        VARCHAR(10) COMMENT '渠道：堂食/外卖',
    order_quantity INT,
    order_amount   DECIMAL(8,2)
);
































































































